        pending = {"main": None, "other": None}
        main_total = 0
        other_total = 0
        changes_main = 0
        changes_other = 0

        def state_for(conn):
            if pending[conn] is not None:
                return pending[conn]
            return committed

        for act in actions:
            op = act.get("op")
            conn = act.get("connection", "main")
            key = act.get("key")
            val = act.get("value")

            if op == "begin":
                pending[conn] = dict(committed)
            elif op == "commit":
                if pending[conn] is not None:
                    committed = pending[conn]
                    pending[conn] = None
            elif op == "rollback":
                pending[conn] = None
            elif op == "put":
                st = state_for(conn)
                changed = False
                if key in st:
                    if put_mode == "ignore":
                        changed = False
                    else:
                        st[key] = val
                        changed = True
                else:
                    st[key] = val
                    changed = True
                if changed:
                    if conn == "main":
                        changes_main += 1
                        main_total += 1
                        if trigger == "after_insert":
                            main_total += 1
                    else:
                        changes_other += 1
                        other_total += 1
                        if trigger == "after_insert":
                            other_total += 1
