                st = state_for(conn)
                if key in st:
                    st[key] = val
                    if conn == "main":
                        changes_main += 1
                        main_total += 1
                    else:
                        changes_other += 1
                        other_total += 1
            elif op == "delete":
                st = state_for(conn)
